"""Face and eye landmark detection module.This script opens the webcam, detects the face with MediaPipe Face Mesh,marks the landmark points around both eyes, and shows whether a face isdetected in the current frame."""import cv2import mediapipe as mpCAMERA_INDEX = 0WINDOW_NAME = "Eye Landmark Detection - Press Q to Quit"LEFT_EYE_COLOR = (0, 255, 255)RIGHT_EYE_COLOR = (255, 0, 255)NO_FACE_COLOR = (0, 0, 255)SUCCESS_COLOR = (0, 255, 0)POINT_RADIUS = 5LINE_THICKNESS = 2# MediaPipe Face Mesh landmark indexes around the eyes.# These points are enough for visual checking and later blink calculations.LEFT_EYE_LANDMARKS = [    33,    133,    160,    159,    158,    157,    173,    246,    161,    163,    144,    145,    153,    154,    155,]RIGHT_EYE_LANDMARKS = [    362,    263,    387,    386,    385,    384,    398,    466,    388,    390,    373,    374,    380,    381,    382,]LEFT_EYE_CONTOUR = [33, 246, 161, 160, 159, 158, 157, 173, 133, 155, 154, 153, 145, 144, 163, 33]RIGHT_EYE_CONTOUR = [362, 398, 384, 385, 386, 387, 388, 466, 263, 249, 390, 373, 374, 380, 381, 382, 362]def open_camera(camera_index=CAMERA_INDEX):    """Open the selected webcam and return the capture object."""    camera = cv2.VideoCapture(camera_index)    if not camera.isOpened():        raise RuntimeError(            "Camera could not be opened. Check webcam connection or camera index."        )    return cameradef create_face_mesh():    """Create and return a MediaPipe Face Mesh detector."""    face_mesh_module = mp.solutions.face_mesh    return face_mesh_module.FaceMesh(        static_image_mode=False,        max_num_faces=1,        refine_landmarks=True,        min_detection_confidence=0.5,        min_tracking_confidence=0.5,    )def detect_face_landmarks(frame, face_mesh):    """Detect face landmarks in a BGR frame."""    rgb_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)    rgb_frame.flags.writeable = False    results = face_mesh.process(rgb_frame)    return results.multi_face_landmarksdef landmark_to_pixel(landmark, frame_width, frame_height):    """Convert a normalized MediaPipe landmark to pixel coordinates."""    x = int(landmark.x * frame_width)    y = int(landmark.y * frame_height)    return x, ydef get_landmark_pixels(face_landmarks, indexes, frame_width, frame_height):    """Convert a list of landmark indexes to pixel coordinates."""    points = []    for index in indexes:        landmark = face_landmarks.landmark[index]        points.append(landmark_to_pixel(landmark, frame_width, frame_height))    return pointsdef draw_eye_points(frame, points, color):    """Draw large landmark points on the frame."""    for point in points:        cv2.circle(frame, point, POINT_RADIUS, color, -1)        cv2.circle(frame, point, POINT_RADIUS + 2, (255, 255, 255), 1)    return framedef draw_eye_contour(frame, points, color):    """Connect eye landmark points with visible contour lines."""    for start_point, end_point in zip(points, points[1:]):        cv2.line(frame, start_point, end_point, color, LINE_THICKNESS)    return framedef draw_eye_landmarks(frame, face_landmarks):    """Draw right and left eye landmark points and contours on the frame."""    frame_height, frame_width, _ = frame.shape    left_eye_points = get_landmark_pixels(        face_landmarks,        LEFT_EYE_LANDMARKS,        frame_width,        frame_height,    )    right_eye_points = get_landmark_pixels(        face_landmarks,        RIGHT_EYE_LANDMARKS,        frame_width,        frame_height,    )    left_eye_contour = get_landmark_pixels(        face_landmarks,        LEFT_EYE_CONTOUR,        frame_width,        frame_height,    )    right_eye_contour = get_landmark_pixels(        face_landmarks,        RIGHT_EYE_CONTOUR,        frame_width,        frame_height,    )    frame = draw_eye_contour(frame, left_eye_contour, LEFT_EYE_COLOR)    frame = draw_eye_contour(frame, right_eye_contour, RIGHT_EYE_COLOR)    frame = draw_eye_points(frame, left_eye_points, LEFT_EYE_COLOR)    frame = draw_eye_points(frame, right_eye_points, RIGHT_EYE_COLOR)    return framedef draw_status(frame, face_detected, eye_landmarks_detected):    """Draw face detection status on the frame."""    if not face_detected:        status_text = "No face detected"        color = NO_FACE_COLOR        font_scale = 1.4        thickness = 3    elif eye_landmarks_detected:        status_text = "Eye landmarks detected"        color = SUCCESS_COLOR        font_scale = 1        thickness = 2    else:        status_text = "Face detected"        color = SUCCESS_COLOR        font_scale = 1        thickness = 2    cv2.putText(        frame,        status_text,        (20, 40),        cv2.FONT_HERSHEY_SIMPLEX,        font_scale,        color,        thickness,        cv2.LINE_AA,    )    return framedef print_detection_status(current_status, previous_status):    """Print status changes to the terminal without flooding the output."""    if current_status != previous_status:        print(current_status)    return current_statusdef run_eye_landmark_detection():    """Run the real-time face and eye landmark detection loop."""    camera = open_camera()    face_mesh = create_face_mesh()    previous_status = None    try:        while True:            success, frame = camera.read()            if not success:                print("Frame could not be read from the camera.")                break            face_landmarks_list = detect_face_landmarks(frame, face_mesh)            face_detected = face_landmarks_list is not None            eye_landmarks_detected = False            if face_detected:                face_landmarks = face_landmarks_list[0]                frame = draw_eye_landmarks(frame, face_landmarks)                eye_landmarks_detected = True            if eye_landmarks_detected:                current_status = "Eye landmarks detected"            elif face_detected:                current_status = "Face detected, but eye landmarks not detected"            else:                current_status = "No face detected"            previous_status = print_detection_status(current_status, previous_status)            frame = draw_status(frame, face_detected, eye_landmarks_detected)            cv2.imshow(WINDOW_NAME, frame)            key = cv2.waitKey(1) & 0xFF            if key == ord("q"):                break    finally:        camera.release()        face_mesh.close()        cv2.destroyAllWindows()if __name__ == "__main__":    run_eye_landmark_detection()